// Extract the first input item (assuming there's only one)
const inputItem = $input.all()[0];

// Clean the JSON string by removing markdown code fences
const cleanOutput = inputItem.json.output.replace(/```json|```/g, "").trim();

// Parse the cleaned JSON string
const parsedData = JSON.parse(cleanOutput);

// Return directly as it matches your target format
return parsedData;
